using ClosedXML.Excel; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using QRCoder; using QuestPDF.Fluent; using QuestPDF.Helpers; using QuestPDF.Infrastructure; using SmartIT.Application; using SmartIT.Domain;
namespace SmartIT.Web.Controllers;
[Authorize(Roles="Admin")] public class ReportsController(IRepository<Asset> assets):Controller { public async Task<FileResult> AssetsCsv(){var rows=await assets.GetAllAsync();var csv="AssetTag,Name,Type,Status\n"+string.Join("\n",rows.Select(x=>$"{x.AssetTag},{x.Name},{x.Type},{x.Status}"));return File(System.Text.Encoding.UTF8.GetBytes(csv),"text/csv","assets.csv");} public async Task<FileResult> AssetsExcel(){var rows=await assets.GetAllAsync();using var wb=new XLWorkbook();var ws=wb.Worksheets.Add("Assets");ws.Cell(1,1).InsertTable(rows.Select(x=>new {x.AssetTag,x.Name,Type=x.Type.ToString(),Status=x.Status.ToString()}));using var ms=new MemoryStream();wb.SaveAs(ms);return File(ms.ToArray(),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","assets.xlsx");} public async Task<FileResult> AssetsPdf(){var rows=await assets.GetAllAsync();var bytes=Document.Create(c=>c.Page(p=>{p.Margin(25);p.Content().Column(col=>{col.Item().Text("SmartIT Pro - Asset Report").FontSize(20).Bold();foreach(var x in rows)col.Item().Text($"{x.AssetTag} | {x.Name} | {x.Type} | {x.Status}");});})).GeneratePdf();return File(bytes,"application/pdf","assets.pdf");} public IActionResult Qr(Guid id){using var q=new QRCodeGenerator();using var data=q.CreateQrCode($"smartit://asset/{id}",QRCodeGenerator.ECCLevel.Q);var png=new PngByteQRCode(data).GetGraphic(12);return File(png,"image/png");} }
